import {
  Mesh,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  Group,
  PointLight,
  AmbientLight
} from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const mainGroup = new Group();

  // Create local cleanup array
  const disposables = [];
  const activeTimelines = [];

  // Define Colors from visualSpec
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. BACKDROP: Engineered vertical gradient stage to prevent FLAT_VOID
  const backdropGeo = new PlaneGeometry(8, 6.5);
  disposables.push(backdropGeo);

  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.7,
    metalness: 0.2,
    depthWrite: false
  });
  disposables.push(backdropMat);

  // Gradient from ink to surface
  const uvNode = uv();
  const cBottom = color(colors.surface);
  const cTop = color(colors.ink);
  backdropMat.colorNode = mix(cBottom, cTop, uvNode.y);

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -2.0;
  mainGroup.add(backdropMesh);

  // 2. HERO PLATE: Machined-metal surface showing the feature-card texture
  const plateWidth = 4.2;
  const plateHeight = 2.6;
  const plateGeo = new PlaneGeometry(plateWidth, plateHeight);
  disposables.push(plateGeo);

  const plateMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.55, // Machined metal PBR
    transparent: true,
    opacity: 0.0 // Handled by entrance animation
  });
  disposables.push(plateMat);

  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.position.set(0, 0.2, 0);
  mainGroup.add(plateMesh);

  // Load the feature-card texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      plateMat.map = texture;
      plateMat.needsUpdate = true;
    }).catch(err => console.error("Error loading image asset:", err));
  }

  // 3. LIGHTING: Local directional & rim highlights (Nova Atelier concept)
  const keyLight = new PointLight(colors.paper, 1.4, 8);
  keyLight.position.set(-2, 2, 2.5);
  mainGroup.add(keyLight);

  const rimLight = new PointLight(colors.accent, 1.1, 6);
  rimLight.position.set(2.5, -2, -1);
  mainGroup.add(rimLight);

  // 4. TYPOGRAPHY: Render text via ctx.fontAtlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textString = items[0]?.text ?? "A machined-metal watch atelier landing with catalog, pricing, jo";

  const textElement = ctx.fontAtlas.createText(textString, {
    fontSize: 24,
    color: colors.paper,
    align: 'center',
    maxWidthPx: 750
  });

  if (textElement) {
    textElement.position.set(0, -1.5, 0.1);
    mainGroup.add(textElement);
  }

  // 5. MOTION: Weighted-settle entrance animation
  plateMesh.position.y = -0.1;
  const entranceTl = gsap.timeline();
  activeTimelines.push(entranceTl);

  entranceTl.to(plateMat, {
    opacity: 1,
    duration: 0.6,
    ease: 'power2.out'
  }, 0);

  entranceTl.to(plateMesh.position, {
    y: 0.2,
    duration: 1.1,
    ease: 'power4.out'
  }, 0);

  if (textElement) {
    textElement.position.y = -1.8;
    entranceTl.to(textElement.position, {
      y: -1.5,
      duration: 1.2,
      ease: 'power3.out'
    }, 0.15);
  }

  // 6. CLEANUP HANDLER
  mainGroup.userData = {
    cleanup() {
      activeTimelines.forEach(tl => tl.kill());
      disposables.forEach(d => d.dispose());
    }
  };

  return mainGroup;
}
